[patterns/security/api-microservices/PTN-SEC-API-003-mtls-authentication-pattern.md#component-3-service-mtls-configuration-net]

#### Component 3: Service mTLS Configuration (.NET)

Configure ASP.NET Core service to use mTLS:

```csharp
// Program.cs - ASP.NET Core mTLS configuration
using System.Security.Cryptography.X509Certificates;

var builder = WebApplication.CreateBuilder(args);

// Configure Kestrel to require client certificates
builder.WebHost.ConfigureKestrel(options =>
{
    options.ConfigureHttpsDefaults(httpsOptions =>
    {
        // Require client certificate for mTLS
        httpsOptions.ClientCertificateMode = ClientCertificateMode.RequireCertificate;

        // Custom validation of client certificate
        httpsOptions.ClientCertificateValidation = (cert, chain, errors) =>
        {
            // Validate certificate against internal CA
            return ValidateClientCertificate(cert, chain, errors);
        };
    });

    // Listen on HTTPS with mTLS
    options.ListenAnyIP(8443, listenOptions =>
    {
        listenOptions.UseHttps(httpsOptions =>
        {
            // Load server certificate from Kubernetes secret mount
            var certPath = "/etc/certs/tls.crt";
            var keyPath = "/etc/certs/tls.key";

            httpsOptions.ServerCertificate = X509Certificate2.CreateFromPemFile(certPath, keyPath);
            httpsOptions.ClientCertificateMode = ClientCertificateMode.RequireCertificate;
        });
    });
});

bool ValidateClientCertificate(
    X509Certificate2 cert,
    X509Chain chain,
    SslPolicyErrors errors)
{
    // Accept self-signed certs if from our internal CA
    if (errors == SslPolicyErrors.RemoteCertificateChainErrors)
    {
        // Load internal CA certificate
        var caCert = LoadInternalCACertificate();

        // Build chain with internal CA
        chain.ChainPolicy.ExtraStore.Add(caCert);
        chain.ChainPolicy.RevocationMode = X509RevocationMode.Online;
        chain.ChainPolicy.VerificationFlags = X509VerificationFlags.NoFlag;

        bool isValid = chain.Build(cert);

        if (isValid)
        {
            // Verify certificate is from our CA
            var rootCert = chain.ChainElements[chain.ChainElements.Count - 1].Certificate;
            if (rootCert.Thumbprint == caCert.Thumbprint)
            {
                // Extract service identity from certificate
                var serviceIdentity = ExtractServiceIdentity(cert);

                // Log successful authentication
                _logger.LogInformation(
                    "Client certificate validated: {ServiceIdentity}, Serial: {Serial}",
                    serviceIdentity, cert.SerialNumber);

                return true;
            }
        }
    }

    _logger.LogWarning(
        "Client certificate validation failed: {Errors}, Subject: {Subject}",
        errors, cert.Subject);

    return false;
}

string ExtractServiceIdentity(X509Certificate2 cert)
{
    // Extract service identity from SAN
    foreach (var extension in cert.Extensions)
    {
        if (extension is X509SubjectAlternativeNameExtension san)
        {
            foreach (var name in san.EnumerateDnsNames())
            {
                if (name.EndsWith(".svc.cluster.local"))
                    return name;
            }

            foreach (var uri in san.EnumerateUniformResourceIdentifiers())
            {
                if (uri.StartsWith("spiffe://gainwell.com/"))
                    return uri;
            }
        }
    }

    return cert.Subject;
}

// Add authentication middleware that uses certificate identity
builder.Services.AddAuthentication(CertificateAuthenticationDefaults.AuthenticationScheme)
    .AddCertificate(options =>
    {
        options.AllowedCertificateTypes = CertificateTypes.All;
        options.Events = new CertificateAuthenticationEvents
        {
            OnCertificateValidated = context =>
            {
                var cert = context.ClientCertificate;
                var serviceIdentity = ExtractServiceIdentity(cert);

                // Create claims from certificate
                var claims = new[]
                {
                    new Claim(ClaimTypes.Name, serviceIdentity),
                    new Claim("certificate_serial", cert.SerialNumber),
                    new Claim("certificate_thumbprint", cert.Thumbprint),
                    new Claim("certificate_subject", cert.Subject)
                };

                context.Principal = new ClaimsPrincipal(
                    new ClaimsIdentity(claims, context.Scheme.Name));

                context.Success();
                return Task.CompletedTask;
            }
        };
    });

var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();
app.Run();
```

