[patterns/security/api-microservices/PTN-SEC-API-003-mtls-authentication-pattern.md#component-4-http-client-mtls-configuration-net]

#### Component 4: HTTP Client mTLS Configuration (.NET)

Configure HTTP client to present client certificate:

```csharp
// ServiceCollectionExtensions.cs
public static class MtlsHttpClientExtensions
{
    public static IHttpClientBuilder AddMtlsHttpClient<TClient>(
        this IServiceCollection services,
        string name,
        Action<HttpClient> configureClient = null)
        where TClient : class
    {
        return services.AddHttpClient<TClient>(name, configureClient)
            .ConfigurePrimaryHttpMessageHandler(sp =>
            {
                var certProvider = sp.GetRequiredService<IClientCertificateProvider>();
                var logger = sp.GetRequiredService<ILogger<TClient>>();

                var handler = new HttpClientHandler();

                // Load client certificate
                var clientCert = certProvider.GetClientCertificate();
                handler.ClientCertificates.Add(clientCert);

                // Configure server certificate validation
                handler.ServerCertificateCustomValidationCallback = (request, cert, chain, errors) =>
                {
                    return ValidateServerCertificate(cert, chain, errors, logger);
                };

                // Enable HTTP/2 for better performance with TLS
                handler.SslProtocols = SslProtocols.Tls13 | SslProtocols.Tls12;

                return handler;
            })
            .SetHandlerLifetime(TimeSpan.FromMinutes(5)); // Recreate handler to pick up renewed certs
    }

    private static bool ValidateServerCertificate(
        X509Certificate2 cert,
        X509Chain chain,
        SslPolicyErrors errors,
        ILogger logger)
    {
        if (errors == SslPolicyErrors.None)
            return true;

        // Load internal CA and validate chain
        var caCert = LoadInternalCACertificate();
        chain.ChainPolicy.ExtraStore.Add(caCert);

        bool isValid = chain.Build(cert);

        if (!isValid)
        {
            logger.LogError(
                "Server certificate validation failed: {Subject}, Errors: {Errors}",
                cert.Subject, errors);
        }

        return isValid;
    }
}

// ClientCertificateProvider.cs
public interface IClientCertificateProvider
{
    X509Certificate2 GetClientCertificate();
}

public class KubernetesCertificateProvider : IClientCertificateProvider
{
    private readonly ILogger<KubernetesCertificateProvider> _logger;
    private readonly string _certPath;
    private readonly string _keyPath;
    private X509Certificate2 _cachedCertificate;
    private DateTime _cacheExpiration;

    public KubernetesCertificateProvider(
        IConfiguration configuration,
        ILogger<KubernetesCertificateProvider> logger)
    {
        _logger = logger;
        _certPath = configuration["Certificates:ClientCertPath"] ?? "/etc/certs/tls.crt";
        _keyPath = configuration["Certificates:ClientKeyPath"] ?? "/etc/certs/tls.key";
    }

    public X509Certificate2 GetClientCertificate()
    {
        // Check if cached certificate is still valid
        if (_cachedCertificate != null && DateTime.UtcNow < _cacheExpiration)
        {
            return _cachedCertificate;
        }

        try
        {
            // Load certificate from Kubernetes secret mount
            _cachedCertificate = X509Certificate2.CreateFromPemFile(_certPath, _keyPath);

            // Cache until 80% of certificate lifetime
            var lifetime = _cachedCertificate.NotAfter - _cachedCertificate.NotBefore;
            _cacheExpiration = DateTime.UtcNow.Add(lifetime * 0.8);

            _logger.LogInformation(
                "Loaded client certificate: {Subject}, Expires: {Expiration}",
                _cachedCertificate.Subject, _cachedCertificate.NotAfter);

            return _cachedCertificate;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to load client certificate from {Path}", _certPath);
            throw;
        }
    }
}

// Usage in service
public class ClaimsApiClient
{
    private readonly HttpClient _httpClient;

    public ClaimsApiClient(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<Claim> GetClaimAsync(string claimId)
    {
        // mTLS authentication automatic via configured handler
        var response = await _httpClient.GetAsync($"https://claims-api.prod.svc.cluster.local/claims/{claimId}");
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Claim>();
    }
}

// Startup.cs registration
services.AddSingleton<IClientCertificateProvider, KubernetesCertificateProvider>();
services.AddMtlsHttpClient<ClaimsApiClient>("ClaimsApi", client =>
{
    client.BaseAddress = new Uri("https://claims-api.prod.svc.cluster.local");
    client.Timeout = TimeSpan.FromSeconds(30);
});
```

