#### Best Practice 6: Implement Certificate Pinning for Critical Services

**Guideline:** For highly sensitive services, implement certificate pinning to prevent CA compromise attacks.

```csharp
// Certificate pinning for critical service
public class PinnedCertificateValidator
{
    private readonly HashSet<string> _pinnedThumbprints;

    public PinnedCertificateValidator(IConfiguration config)
    {
        _pinnedThumbprints = new HashSet<string>(
            config.GetSection("PinnedCertificates").Get<string[]>());
    }

    public bool ValidatePinnedCertificate(X509Certificate2 cert)
    {
        // Check if certificate thumbprint is in pinned list
        if (_pinnedThumbprints.Contains(cert.Thumbprint))
        {
            return true;
        }

        // Log pinning failure (possible CA compromise)
        _logger.LogWarning(
            "Certificate pinning failed: {Subject}, Thumbprint: {Thumbprint}",
            cert.Subject, cert.Thumbprint);

        return false;
    }
}
```

