        _watcher = new FileSystemWatcher(Path.GetDirectoryName(_certPath));
        _watcher.Filter = Path.GetFileName(_certPath);
        _watcher.Changed += OnCertificateChanged;
        _watcher.EnableRaisingEvents = true;

