### Example 3: Legacy VM Integration with mTLS

**Scenario:** Legacy .NET Framework service on Windows VM needs mTLS to communicate with Kubernetes services.

**Implementation:**

```csharp
// Legacy service on Windows VM
public class LegacyServiceMtlsClient
{
    private readonly X509Certificate2 _clientCertificate;
    private readonly HttpClient _httpClient;

    public LegacyServiceMtlsClient(IConfiguration config)
    {
        // Load client certificate from Windows certificate store
        var thumbprint = config["ClientCertificate:Thumbprint"];
        _clientCertificate = GetCertificateFromStore(thumbprint);

        var handler = new HttpClientHandler();
        handler.ClientCertificates.Add(_clientCertificate);

        // Validate server certificate against internal CA
        handler.ServerCertificateCustomValidationCallback = ValidateServerCertificate;

        _httpClient = new HttpClient(handler);
        _httpClient.BaseAddress = new Uri("https://claims-api.prod.gainwell.internal");
    }

    private X509Certificate2 GetCertificateFromStore(string thumbprint)
    {
        using (var store = new X509Store(StoreName.My, StoreLocation.LocalMachine))
        {
            store.Open(OpenFlags.ReadOnly);
            var certs = store.Certificates.Find(
                X509FindType.FindByThumbprint,
                thumbprint,
                validOnly: true);

            if (certs.Count == 0)
                throw new Exception($"Certificate with thumbprint {thumbprint} not found");

            return certs[0];
        }
    }

    private bool ValidateServerCertificate(
        HttpRequestMessage request,
        X509Certificate2 cert,
        X509Chain chain,
        SslPolicyErrors errors)
    {
        // Load internal CA from Windows trusted root store
        var caCert = GetInternalCACertificate();
        chain.ChainPolicy.ExtraStore.Add(caCert);

        return chain.Build(cert);
    }

    public async Task<string> GetClaimAsync(string claimId)
    {
        var response = await _httpClient.GetAsync($"/api/claims/{claimId}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }
}
```

**Certificate Management:**
```powershell
# PowerShell script to install certificate on Windows VM
# Run as Administrator

# 1. Request certificate from Vault
$vaultToken = $env:VAULT_TOKEN
$headers = @{ "X-Vault-Token" = $vaultToken }

$body = @{
    common_name = "legacy-service.prod.gainwell.internal"
    alt_names = "legacy-service.prod.gainwell.internal"
    ttl = "2160h"  # 90 days for legacy system
} | ConvertTo-Json

$response = Invoke-RestMethod `
    -Uri "https://vault.gainwell.internal:8200/v1/pki_int/issue/service-mtls" `
    -Method POST `
    -Headers $headers `
    -Body $body `
    -ContentType "application/json"

# 2. Import certificate to Windows certificate store
$cert = $response.data.certificate
$key = $response.data.private_key

$pfx = ConvertTo-PfxCertificate -Certificate $cert -PrivateKey $key
Import-PfxCertificate -FilePath $pfx `
    -CertStoreLocation "Cert:\LocalMachine\My" `
    -Password (ConvertTo-SecureString -String "temp" -AsPlainText -Force)

# 3. Schedule certificate renewal (Task Scheduler)
# Renew 30 days before expiration
```

**Measured Results:**
- **Legacy VM successfully integrated** with Kubernetes mTLS
- **90-day certificate lifetime** (longer than Kubernetes 24h due to manual renewal)
- **Scheduled renewal** via Windows Task Scheduler
- **Same security level** as Kubernetes services (certificate-based authentication)
